import java.util.*;

class Solution {
    private List<List<String>> res = new ArrayList<>();

    public List<List<String>> solveNQueens(int n) {
        char[][] board = new char[n][n];
        for (char[] row : board) Arrays.fill(row, '.');
        backtrack(0, board, new boolean[n], new boolean[2 * n], new boolean[2 * n], n);
        return res;
    }

    private void backtrack(int row, char[][] board, boolean[] cols, boolean[] diag, boolean[] anti, int n) {
        if (row == n) {
            List<String> sol = new ArrayList<>();
            for (char[] r : board) sol.add(new String(r));
            res.add(sol);
            return;
        }
        for (int col = 0; col < n; col++) {
            int d = row - col + n, a = row + col;
            if (cols[col] || diag[d] || anti[a]) continue;
            cols[col] = diag[d] = anti[a] = true;
            board[row][col] = 'Q';
            backtrack(row + 1, board, cols, diag, anti, n);
            board[row][col] = '.';
            cols[col] = diag[d] = anti[a] = false;
        }
    }
}
